import { esc } from '../state.js';
import { matchupHeatmapHtml, residualHeatmapHtml, comparisonPlotHtml, behaviorPlotsHtml, learningTrendHtml, lineageGraphHtml } from './evolution-analytics-charts.mjs';
import { lineChart } from '../chart-toolkit.js';
import { behaviorDeltas } from './evolution-research.mjs';
import { WEIGHT_FEATURES, WEIGHT_BOUND } from './weighted-heuristic.mjs';
import { projectModel, lineageNodes, residualRows, behaviorPair, filterRecords, draftWeights, shortId, finite } from './evolution-view-model.mjs';

export const percent = n => finite(n) ? `${(n * 100).toFixed(1)}%` : 'Unavailable';
const number = n => finite(n) ? n.toFixed(2) : 'Unavailable';
const inspect = (kind, id, label = shortId(id)) => id ? `<button class="evo-link" data-evo-inspect="${kind}:${esc(id)}">${esc(label)}</button>` : 'Unavailable';
const badge = (text, type = '') => `<span class="evo-badge ${type ? `evo-badge-${type}` : ''}">${esc(text)}</span>`;
const empty = (title, text, surface) => `<div class="evo-empty"><span class="evo-eyebrow">EVIDENCE FIRST</span><h3>${esc(title)}</h3><p>${esc(text)}</p>${surface ? `<button data-evo-surface="${surface}">Open ${surface}</button>` : ''}</div>`;
const raw = (record, label = 'Raw evidence') => `<details class="evo-diagnostics"><summary>${esc(label)}</summary><button class="ghost-button" data-evo-copy-record>Copy diagnostics</button><pre>${esc(JSON.stringify(record, null, 2))}</pre></details>`;
const table = (headers, rows) => `<div class="evo-table-scroll" tabindex="0" aria-label="Scrollable evidence table"><table><thead><tr>${headers.map(h => `<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const idRow = (name, value) => `<div class="evo-inspector-field"><dt>${esc(name)}</dt><dd>${value ? `<code>${esc(value)}</code><button class="evo-copy" data-evo-copy="${esc(value)}" aria-label="Copy ${esc(name)}">Copy</button>` : 'Unavailable'}</dd></div>`;

export function overviewHtml(project, arena) {
  const model = projectModel(project), run = arena.run;
  return `<div class="evo-workspace-title"><div><span class="evo-eyebrow">COMMAND CENTER</span><h3>Observe. Compare. Reproduce.</h3><p>Training selects a policy. Held-out evidence measures it.</p></div><button data-evo-surface="evolution">Configure experiment</button></div>
    <div class="evo-overview-stats">${[['Research state', project?.experiment.status ?? 'No experiment'], ['Committed generations', project ? project.generations.length : 'Not started'], ['Held-out coverage', project ? `${model.coverage.complete} / ${model.coverage.total} recorded roots / selections` : 'Not evaluated'], ['Recorded faults', project ? project.faults.length : 'No experiment']].map(([k,v]) => `<div><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div>
    <div class="evo-overview-grid"><section class="evo-workbench"><h4>Independent lineage heads</h4>${model.heads.length ? model.heads.map((h,i) => `<div class="evo-head evo-lineage-${i ? 'b' : 'a'}"><span class="evo-eyebrow">${esc(h.root.agentId)} / GENERATION ${h.checkpoint.generation}</span><h4>${inspect('checkpoint',h.checkpoint.checkpointId,h.checkpoint.policyId)}</h4><p>${h.evaluation ? badge('Held-out complete','evaluation') : badge('Not evaluated','unavailable')} ${badge(`${h.generations.length} committed selections`)}</p><p><code>${esc(shortId(h.checkpoint.checkpointId,26))}</code></p><button data-evo-inspect="checkpoint:${h.checkpoint.checkpointId}">Inspect ancestry & evidence</button></div>`).join('') : empty('No research experiment','Start frozen arena games, or create A0/B0 to study independent weighted lineages.','evolution')}</section>
    <section class="evo-workbench"><h4>Execution & provenance</h4><dl>${idRow('Scientific ID',project?.experiment.scientificId)}${idRow('Suite',project?.suite.suiteId)}</dl>${project?.packs.map(p => `<p>${badge(p.purpose,p.purpose.toLowerCase())} ${p.seeds.length} explicit seeds · mirrored seats<br>${inspect('pack',p.packId)}</p>`).join('') ?? '<p>No frozen packs committed.</p>'}<p>Current arena: ${esc(run?.status ?? 'IDLE')} · ${run ? `${run.records.length} accepted games` : 'No game evidence'}</p><p>${project?.regressions?.length ?? 0} descriptive regression findings.</p><button data-evo-surface="evidence">Open evidence workbench</button></section></div>
    ${project?.faults.length ? `<section class="evo-workbench evo-fault-panel"><h4>Recorded failures remain evidence</h4>${project.faults.slice(-3).map((f,i) => `<p>${inspect('fault',String(project.faults.length - Math.min(3,project.faults.length)+i),f.stage ?? 'Research fault')} · ${esc(f.message.split('\n')[0])}</p>`).join('')}</section>` : ''}`;
}

export function lineagesHtml(project, state) {
  if (!project) return empty('No lineage ledger','Create or load a research experiment. Frozen baselines remain immutable.');
  const model = projectModel(project), nodes = lineageNodes(project,{lineage:state.lineage,from:state.from,to:state.to,query:state.search,findingsOnly:state.findingsOnly,faultsOnly:state.faultsOnly});
  const page = Math.min(state.page, Math.max(0,Math.ceil(nodes.length/25)-1)), shown=nodes.slice(page*25,page*25+25);
  return `<div class="evo-workspace-title"><div><span class="evo-eyebrow">APPEND-ONLY LEDGER</span><h3>Lineages & generations</h3><p>Nodes represent recorded roots and committed selections. Candidates live in generation inspection.</p></div></div>
    <div class="evo-filterbar"><label>Lineage<select data-evo-filter="lineage"><option value="all">All lineages</option>${model.roots.map(r => `<option value="${r.lineageId}" ${state.lineage===r.lineageId?'selected':''}>${esc(r.agentId)}</option>`).join('')}</select></label><label>From<input data-evo-filter="from" type="number" min="0" max="100" value="${state.from}"></label><label>To<input data-evo-filter="to" type="number" min="0" max="100" value="${state.to}"></label><label class="evo-check"><input data-evo-filter="findingsOnly" type="checkbox" ${state.findingsOnly?'checked':''}>Regressions</label><label class="evo-check"><input data-evo-filter="faultsOnly" type="checkbox" ${state.faultsOnly?'checked':''}>Faults</label><button data-evo-jump="root">Root</button><button data-evo-jump="latest">Latest</button></div>
    ${lineageGraphHtml(project)}${learningTrendHtml(project)}${residualHeatmapHtml(project,WEIGHT_FEATURES,WEIGHT_BOUND)}
    <div class="evo-lineage-rail" aria-label="Recorded checkpoint sequence">${shown.map(n => `<article class="evo-lineage-node evo-lineage-${n.checkpoint.agentId==='B'?'b':'a'} ${state.inspect===`checkpoint:${n.checkpoint.checkpointId}`?'is-selected':''}"><div class="evo-node-track" aria-hidden="true">${n.checkpoint.generation===0?'○':'●'}</div><div><span class="evo-eyebrow">${esc(n.checkpoint.agentId)} · GENERATION ${n.checkpoint.generation}</span><h4>${inspect('checkpoint',n.checkpoint.checkpointId,shortId(n.checkpoint.checkpointId,23))}</h4><p>${n.generation ? `${inspect('generation',n.generation.generationId,'Selection record')} · ${n.generation.candidateCheckpointIds.length} candidates · ${n.checkpoint.mutation?.kind==='RETAIN_PARENT'?'Retained parent':esc(n.checkpoint.mutation?.parameter ?? 'Selected descendant')}` : 'Immutable root checkpoint'}</p><p>${badge(n.evaluation?'EVALUATION complete':'EVALUATION pending',n.evaluation?'evaluation':'unavailable')} ${n.regressions.length?badge(`${n.regressions.length} regressions`,'warning'):''} ${n.faults.length?badge(`${n.faults.length} faults`,'danger'):''}</p></div></article>`).join('') || empty('No matching records','Adjust generation, lineage or finding filters. Missing records are not zero observations.')}</div>
    <div class="evo-pagination"><span>${nodes.length} matching nodes · ${shown.length} shown</span><button data-evo-page="-1" ${page===0?'disabled':''}>Previous</button><button data-evo-page="1" ${page*25+25>=nodes.length?'disabled':''}>Next</button></div>
    <details><summary>All checkpoint identities · ${project.checkpoints.length}</summary>${table(['Checkpoint','Generation','Parent','State'],filterRecords(project.checkpoints,state.search,['checkpointId','agentId','policyId','generation']).slice(0,50).map(cp => `<tr><td>${inspect('checkpoint',cp.checkpointId)}</td><td>${cp.generation}</td><td>${inspect('checkpoint',cp.parentCheckpointId)}</td><td>${cp.schemaVersion===2?'Weighted / immutable':'Frozen baseline'}</td></tr>`))}<p>First 50 matching checkpoints; use search to narrow.</p></details>`;
}

export function evidenceHtml(project, state, comparison, busy, historical = false) {
  if (!project) return empty('No research evidence','Load an experiment or collect a held-out frozen suite. Arena runs stay canonical here and are also indexed for Strategy analysis.','evolution');
  const options = selected => project.checkpoints.map(cp => `<option value="${cp.checkpointId}" ${cp.checkpointId===selected?'selected':''}>${esc(cp.agentId)}${cp.generation} · ${esc(shortId(cp.checkpointId))}</option>`).join('');
  const modes = [['evaluations','Evaluations'],['comparison','Compare'],['behavior','Behavior'],['regressions','Regressions']];
  let content;
  if(state.evidenceMode==='comparison') content=comparisonHtml(comparison,project,state);
  else if(state.evidenceMode==='behavior') content=behaviorHtml(project,state);
  else if(state.evidenceMode==='regressions') content=regressionHtml(project,state);
  else content=evaluationsHtml(project,state);
  return `<div class="evo-workspace-title"><div><span class="evo-eyebrow">FROZEN RESEARCH WORKBENCH</span><h3>Evidence & comparison</h3><p>Latest complete matching evidence for comparisons. Every attempt remains inspectable.</p></div><button data-evo-action="evaluate" ${busy?'disabled':''}>Run held-out suite</button></div>
    <div class="evo-filterbar"><label>Left / before<select id="evo-workbench-left" data-evo-select="left" ${historical?'disabled':''}>${options(state.left)}</select></label><button data-evo-pair="swap" aria-label="Swap comparison checkpoints" ${historical?'disabled':''}>⇄ Swap</button><label>Right / after<select id="evo-workbench-right" data-evo-select="right" ${historical?'disabled':''}>${options(state.right)}</select></label><button data-evo-pair="root" ${historical?'disabled':''}>Root vs selected</button><button data-evo-pair="parent" ${historical?'disabled':''}>Parent vs child</button><button data-evo-pair="latest" ${historical?'disabled':''}>A latest vs B latest</button><button data-evo-action="compare" ${historical?'disabled':''}>Compare</button></div>
    <div class="evo-tabs" role="tablist" aria-label="Evidence workspace">${modes.map(([key,label]) => `<button role="tab" id="evo-tab-${key}" aria-controls="evo-evidence-content" aria-selected="${state.evidenceMode===key}" tabindex="${state.evidenceMode===key?0:-1}" data-evo-evidence="${key}">${label}</button>`).join('')}</div><div id="evo-evidence-content" role="tabpanel" aria-labelledby="evo-tab-${state.evidenceMode}">${content}</div>`;
}

function evaluationsHtml(project,state) {
  const rows=filterRecords(project.evaluations,state.search,['evaluationId','candidateCheckpointId','purpose','status']), purpose=state.purpose;
  const filtered=rows.filter(e=>purpose==='all'||e.purpose===purpose), shown=filtered.slice(-30).reverse();
  return `<div class="evo-filterbar"><label>Evidence purpose<select data-evo-filter="purpose"><option value="all">Both, labeled separately</option>${['TRAINING','EVALUATION'].map(p=>`<option ${purpose===p?'selected':''}>${p}</option>`).join('')}</select></label><span>${filtered.length} attempts · latest 30 shown</span></div>${state.search || purpose==='TRAINING'?'':matchupHeatmapHtml(project)}<div id="evo-research-evaluations">${shown.map(e=>`<section class="evo-workbench"><header><h4>${inspect('evaluation',e.evaluationId,shortId(e.candidateCheckpointId,23))}</h4>${badge(e.purpose,e.purpose.toLowerCase())} ${badge(e.status,e.status==='COMPLETE'?'':'warning')}</header><p>${inspect('pack',e.packId)} · ${inspect('checkpoint',e.candidateCheckpointId,'Candidate checkpoint')}</p>${table(['Opponent','Paired score','95% bounds','Clean / failed / unresolved','Margin','First-seat wins','Execution'],e.matchups.map(m=>`<tr><td>${esc(m.opponentPolicyId)}</td><td>${percent(m.metrics.pairedScore)}</td><td>${m.metrics.pairedScoreInterval95?.map(percent).join(' – ')??'Unavailable'}</td><td>${m.metrics.clean} / ${m.metrics.aborted} / ${m.metrics.unresolved}</td><td>${number(m.metrics.meanScoreDifference)}</td><td>${percent(m.metrics.firstPlayerWinRate)}</td><td>${inspect('run',m.runId)}</td></tr>`))}</section>`).join('') || empty('Not evaluated','Collect evidence to see measured opponent results. No score is inferred.')}</div>`;
}

function comparisonHtml(comparison,project,state) {
  const a=project.checkpoints.find(cp=>cp.checkpointId===state.left),b=project.checkpoints.find(cp=>cp.checkpointId===state.right);
  if(!comparison || comparison.a!==state.left || comparison.b!==state.right)return empty('Choose a comparison','Select two checkpoints, then Compare. Matching evidence is required.');
  return `<section id="evo-checkpoint-comparison" class="evo-workbench"><h4>Checkpoint comparison</h4><p>${esc(comparison.selectionPolicy)} ${esc(comparison.interpretation)}</p><p>${inspect('checkpoint',a.checkpointId,'Before checkpoint')} → ${inspect('checkpoint',b.checkpointId,'After checkpoint')}</p>${comparisonPlotHtml(comparison,project)}${table(['Opponent','Before','After','Paired-score Δ','Margin Δ','Evidence'],comparison.matchups.map(m=>`<tr><td>${esc(m.opponent)}</td><td>${percent(m.before)}</td><td>${percent(m.after)}</td><td>${finite(m.delta)?`${(100*m.delta).toFixed(1)} pp`:'Unavailable'}</td><td>${number(m.scoreMarginDelta)}</td><td>${inspect('evaluation',m.beforeEvaluationId,'Before')} / ${inspect('evaluation',m.afterEvaluationId,'After')}</td></tr>`))}${comparison.matchups.length?'':'<p>Comparison unavailable: no complete matching evidence.</p>'}<h5>Recorded residual state</h5>${table(['Feature','Before','After','Δ'],WEIGHT_FEATURES.map(k=>{const x=a.policyState.weights?.[k],y=b.policyState.weights?.[k];return `<tr><td>${k}</td><td>${x??'Not applicable'}</td><td>${y??'Not applicable'}</td><td>${finite(x)&&finite(y)?y-x:'Unavailable'}</td></tr>`;}))}${raw(comparison,'Comparison diagnostics')}</section>`;
}

function behaviorHtml(project,state) {
  const pair=behaviorPair(project,state.left,state.right,state.opponent),delta=pair.available?behaviorDeltas(pair.before,pair.after):null;
  return `<section id="evo-behavior-divergence" class="evo-workbench evo-behavior-summary"><h4>Observed behavior</h4><p>Candidate decisions on a matching held-out pack and frozen opponent. Parameter changes are not behavior.</p><label>Opponent<select data-evo-filter="opponent">${project.suite.checkpoints.map(cp=>`<option value="${cp.policyId}" ${state.opponent===cp.policyId?'selected':''}>${esc(cp.policyId)}</option>`).join('')}</select></label>${delta?.available?`<p>${delta.beforeGames} before / ${delta.afterGames} after games; <b>${delta.beforeDecisions} / ${delta.afterDecisions} candidate decisions</b>.</p><p>${inspect('pack',pair.pack.packId)} · ${inspect('evaluation',pair.beforeEvaluationId,'Before evidence')} / ${inspect('evaluation',pair.afterEvaluationId,'After evidence')}</p>${behaviorPlotsHtml(delta)}${table(['Measured family / tag','Before','After','Δ percentage points'],delta.metrics.slice(0,60).map(m=>`<tr><td>${esc(m.category==='actionRates'?'Family':'Mechanic')}: ${esc(m.key)}</td><td>${percent(m.before)}</td><td>${percent(m.after)}</td><td><span class="evo-delta-bar" style="--delta:${Math.min(100,Math.abs(m.delta)*100)}%">${(m.delta*100).toFixed(2)} pp</span></td></tr>`))}${raw({pair,delta},'Behavior diagnostics')}`:empty('Telemetry unavailable',pair.reason)}<p>Rank/suit usage and direct resource expenditure: not captured.</p></section>`;
}

function regressionHtml(project,state) {
  const rows=filterRecords(project.regressions??[],state.search).filter(r=>{const cp=project.checkpoints.find(c=>c.checkpointId===r.checkpointId);return state.lineage==='all'||cp?.lineageId===state.lineage;});
  return `<section id="evo-regression-summary" class="evo-workbench"><h4>Observed matchup regressions</h4><p>Paired-score drops on matching frozen samples. Descriptive findings; uncertainty stays visible.</p>${rows.length?table(['Candidate / reference','Opponent','Δ','Uncertainty','Finding'],rows.slice(0,50).map(r=>`<tr><td>${inspect('checkpoint',r.checkpointId)}<br>${inspect('checkpoint',r.referenceCheckpointId)}</td><td>${esc(r.opponent)}</td><td>${(100*r.delta).toFixed(1)} pp</td><td>${esc(r.uncertainty)}</td><td>${inspect('regression',r.findingId,'Inspect / compare')}</td></tr>`)):empty('No recorded regression findings','This does not establish absence of regressions beyond the measured samples.')}${raw(rows,'Regression diagnostics')}<p>${rows.length} matching findings; first 50 shown.</p></section>`;
}

export function inspectorHtml(project,state,arena) {
  const selection=state.inspect;if(!selection)return empty('Select evidence','Choose a checkpoint, generation, evaluation or finding. IDs link across workspaces.');
  const [kind,...parts]=selection.split(':'),id=parts.join(':');
  if(kind==='game'){
    const record=arena.run?.records.find(r=>r.ordinal===Number(id));
    if(!record)return empty('Game unavailable','This game ordinal is absent from the current run.');
    const retained=arena.run.replays.find(r=>r.ordinal===record.ordinal);
    return `<span class="evo-eyebrow">ACCEPTED GAME RECORD</span><h3>Game ${record.ordinal+1} · ${record.swapped?'BA':'AB'}</h3><p>Seed ${record.seed} · ${esc(record.terminationReason)} · ${esc(record.winner)}</p><p>Stored full-turn counter ${record.turns} · mini-turns ${record.miniTurns} · policy decisions ${record.decisions}</p><p>P1 score ${record.scoreP1} · P2 score ${record.scoreP2}</p><dl>${idRow('Run ID',arena.run.runId)}${idRow('Final state hash',record.finalStateHash)}${idRow('Action sequence hash',record.actionSequenceHash)}</dl>${retained?`<button data-evo-surface="forensics">Open retained replay in Forensics</button>`:'<p>Full replay not retained. Slim evidence preserves seed, ordinal, configuration and hashes; export from Ledger.</p>'}${raw(record,'Game telemetry')}`;
  }
  if(kind==='run')return `<h3>Run reference</h3><dl>${idRow('Run ID',id)}</dl><p>A reference does not prove its file exists on this browser origin.</p><button data-evo-load-run="${esc(id)}" ${arena.controlsLocked?'disabled':''}>Load locally available run</button>${arena.controlsLocked?'<p>Stop the current arena or leave historical inspection before loading other evidence.</p>':''}${arena.run?.runId===id?raw({runId:arena.run.runId,kind:arena.run.kind,status:arena.run.status,config:arena.run.config,identity:arena.run.identity,acceptedGames:arena.run.records.length,retainedReplays:arena.run.replays.length},'Run summary diagnostics')+'<p>Inspect sampled commands in Forensics. Export the complete artifact in Ledger.</p>':''}`;
  if(!project)return empty('No project for this selection','Load its experiment to inspect the referenced record.');
  if(kind==='checkpoint')return checkpointHtml(project,state,id);
  if(kind==='generation')return generationHtml(project,id);
  const record=kind==='evaluation'?project.evaluations.find(e=>e.evaluationId===id):kind==='regression'?(project.regressions??[]).find(r=>r.findingId===id):kind==='pack'?project.packs.find(p=>p.packId===id):kind==='fault'?project.faults[Number(id)]:null;
  if(!record)return empty('Selection unavailable','This ID is not present in the current experiment.');
  return `<span class="evo-eyebrow">${esc(kind.toUpperCase())}</span><h3>${esc(kind==='fault'?'Recorded failure':record.purpose??'Evidence record')}</h3>${kind==='fault'?`<p class="danger">${esc(record.message.split('\n')[0])}</p><p>Committed generations remain preserved. Resume retries required compatible work; export if persistence failed.</p>`:''}<dl>${Object.entries(record).filter(([key,v])=>v!==null&&['string','number'].includes(typeof v)&&key!=='message').map(([key,v])=>idRow(key,String(v))).join('')}</dl>${record.checkpointId?inspect('checkpoint',record.checkpointId,'Candidate checkpoint'):''}${record.candidateCheckpointId?inspect('checkpoint',record.candidateCheckpointId,'Candidate checkpoint'):''}${record.referenceCheckpointId?inspect('checkpoint',record.referenceCheckpointId,'Reference checkpoint'):''}${kind==='regression'?`<button data-evo-finding="${esc(id)}">Compare candidate / reference</button>`:''}${kind==='evaluation'?`<h4>Named opponent executions</h4>${record.matchups.map(m=>`<p>${esc(m.opponentPolicyId)} · ${percent(m.metrics.pairedScore)} · ${inspect('run',m.runId)}</p>`).join('')}`:''}${raw(record)}`;
}

function checkpointHtml(project,state,id) {
  const cp=project.checkpoints.find(c=>c.checkpointId===id);if(!cp)return empty('Checkpoint unavailable','The selected ID is not in this project.');
  const rows=residualRows(project,cp,WEIGHT_FEATURES),evals=project.evaluations.filter(e=>e.candidateCheckpointId===id),descendants=project.checkpoints.filter(c=>c.parentCheckpointId===id);
  return `<span class="evo-eyebrow">IMMUTABLE CHECKPOINT / SCHEMA ${cp.schemaVersion}</span><h3>${esc(cp.agentId)} · generation ${cp.generation}</h3><p>${badge(cp.schemaVersion===2?'Experimental weighted':'Frozen shipped policy')} ${cp.protected?badge('Protected'):''}</p><dl>${idRow('Checkpoint ID',cp.checkpointId)}${idRow('Policy',`${cp.policyId} / ${cp.policyVersion}`)}${idRow('Implementation',cp.policyImplementationHash)}${idRow('Lineage',cp.lineageId)}${idRow('Experiment origin',cp.experimentId)}${idRow('Created',cp.createdAt)}</dl><h4>Ancestry</h4><p>Parent: ${inspect('checkpoint',cp.parentCheckpointId)}</p><p>Direct descendants: ${descendants.length}</p>${descendants.slice(0,10).map(c=>inspect('checkpoint',c.checkpointId)).join(' ')}<div class="toolbar"><button data-evo-pair="root">Root vs selected</button><button data-evo-pair="parent" ${cp.parentCheckpointId?'':'disabled'}>Parent vs child</button></div>
    ${rows.length?`<h4>Recorded residuals</h4>${table(['Feature','Value','Δ root','Δ parent'],rows.map(r=>`<tr><td>${r.feature}</td><td>${r.value}</td><td>${r.rootDelta??'Unavailable'}</td><td>${r.parentDelta??'Not applicable'}</td></tr>`))}${draftHtml(cp,state)}`:'<p>Frozen schema-v1 policies have no editable residual state.</p>'}<h4>Recorded evidence · ${evals.length}</h4>${evals.slice(-10).map(e=>`<p>${badge(e.purpose,e.purpose.toLowerCase())} ${badge(e.status)} ${inspect('evaluation',e.evaluationId)}</p>`).join('')||'<p>Not evaluated.</p>'}${raw(cp,'Raw checkpoint')}`;
}

function draftHtml(cp,state) {
  const draft=draftWeights(cp,state.drafts[cp.checkpointId],WEIGHT_FEATURES,WEIGHT_BOUND);
  return `<details class="evo-draft" ${state.draftOpen?'open':''}><summary>Residual draft · non-committed</summary><p>Inspection only. Cannot train, save a checkpoint or predict performance. Bounds ±${WEIGHT_BOUND} come from policy authority.</p><div class="evo-draft-grid">${WEIGHT_FEATURES.map(k=>`<label>${k}<input aria-label="${k} draft slider" type="range" min="-${WEIGHT_BOUND}" max="${WEIGHT_BOUND}" step="1" value="${draft.values[k]}" data-evo-weight="${k}" data-checkpoint="${cp.checkpointId}"><input aria-label="${k} draft value" type="number" min="-${WEIGHT_BOUND}" max="${WEIGHT_BOUND}" step="1" value="${draft.values[k]}" data-evo-weight="${k}" data-checkpoint="${cp.checkpointId}"></label>`).join('')}</div><p id="evo-draft-status" role="status">${draft.valid?'Non-committed draft. Historical weights remain unchanged.':`Invalid draft: ${esc(draft.invalid.join(', '))}`}</p><button data-evo-draft-reset="${cp.checkpointId}">Reset draft</button><button data-evo-draft-copy="${cp.checkpointId}" ${draft.valid?'':'disabled'}>Copy non-committed draft</button><p>Actual last mutation: ${esc(cp.mutation?.kind??'Root')}${cp.mutation?.parameter?` · ${esc(cp.mutation.parameter)} ${cp.mutation.before} → ${cp.mutation.after}`:''}</p></details>`;
}

function generationHtml(project,id) {
  const g=project.generations.find(g=>g.generationId===id);if(!g)return empty('Generation unavailable','Select a committed generation record.');
  const ranks=new Map(g.selection.ranking.map(r=>[r.checkpointId,r])),disqualified=new Map(g.selection.disqualified.map(r=>[r.checkpointId,r]));
  return `<span class="evo-eyebrow">COMMITTED SELECTION</span><h3>Generation ${g.generation}</h3><dl>${idRow('Generation ID',g.generationId)}${idRow('Lineage',g.lineageId)}</dl><p>Parent: ${inspect('checkpoint',g.parentCheckpointId)}</p><p>Selected child: ${inspect('checkpoint',g.selectedCheckpointId)}</p><h4>TRAINING selection evidence</h4><p>${esc(g.selection.criterion)}</p>${table(['Candidate','Training mean','Selection evidence'],g.candidateCheckpointIds.map((cp,i)=>`<tr><td>${inspect('checkpoint',cp,i===0?'Parent candidate':`Mutation #${i}`)}</td><td>${ranks.has(cp)?percent(ranks.get(cp).fitness):'Disqualified'}</td><td>${disqualified.has(cp)?esc(disqualified.get(cp).reason):inspect('evaluation',g.candidateEvaluationIds[i])}</td></tr>`))}<p>TRAINING pack: ${inspect('pack',g.trainingPackId)}</p><p>Held-out pack: ${inspect('pack',g.evaluationPackId)}</p><p>EVALUATION completion: ${project.evaluations.some(e=>e.candidateCheckpointId===g.selectedCheckpointId&&e.packId===g.evaluationPackId&&e.status==='COMPLETE')?'Complete':'Pending / incomplete'}</p><p>Recorded regressions: ${(project.regressions??[]).filter(r=>r.checkpointId===g.selectedCheckpointId).length}</p><p>Operational elapsed: ${finite(g.elapsedMs)?`${(g.elapsedMs/1000).toFixed(2)} s`:'Unavailable'}</p>${raw(g.mutations,'Recorded mutations')}${raw(g,'Raw generation')}`;
}

export function heldOutTrendHtml(project) {
  if(!project?.generations.length)return '';
  const model=projectModel(project),pack=project.packs.find(p=>p.purpose==='EVALUATION'),maximum=Math.max(...project.generations.map(g=>g.generation));
  const series=model.heads.map((head,i)=>({label:`${head.root.agentId} · EVALUATION`,color:i?'var(--evo-lineage-b)':'var(--evo-lineage-a)',values:Array.from({length:maximum+1},(_,n)=>{const cp=n===0?head.root.checkpointId:head.generations.find(g=>g.generation===n)?.selectedCheckpointId;const e=project.evaluations.findLast(e=>e.candidateCheckpointId===cp&&e.packId===pack.packId&&e.suiteId===project.suite.suiteId&&e.status==='COMPLETE'&&e.purpose==='EVALUATION');const score=e?.matchups.find(m=>m.opponentPolicyId==='control')?.metrics.pairedScore;return finite(score)?score*100:null;})}));
  return `<section class="evo-workbench"><h4>Held-out control score by generation</h4>${lineChart({series,xLabels:Array.from({length:maximum+1},(_,i)=>String(i)),minValue:0,maxValue:100,yUnit:'%',ariaLabel:'Recorded A and B held-out paired scores against control; missing evaluations are gaps'})}<p>EVALUATION only · matching frozen control checkpoint / pack. Missing evidence remains gaps.</p></section>`;
}
